shell_commands:
node -e '
import("@re-cinq/eslint-plugin-re-lint").then(m => {
  const plugin = m.default;
  for (const name of ["require-colocated-tests", "test-imports-its-subject", "require-spec-link", "max-expects"]) {
    console.log("=== " + name + " ===");
    console.log(plugin.rules[name].create.toString().slice(0, 1500));
  }
});
'

node -e '
import { readFileSync } from "node:fs";
import { segmentStatements } from "@re-cinq/eslint-plugin-re-lint/spec/spec-segment.js";
import { unlinkedTestableStatements } from "@re-cinq/eslint-plugin-re-lint/spec/spec-status-coverage.js";
const content = readFileSync("specs/hal-engine-config-hooks/spec.md", "utf8");
console.log("segments:", segmentStatements(content));
console.log("unlinked:", unlinkedTestableStatements(content));
'

node -e '
import("@re-cinq/eslint-plugin-re-lint").then(m => {
  const plugin = m.default;
  console.log("=== test-imports-its-subject full ===");
  console.log(plugin.rules["test-imports-its-subject"].meta);
});
' && node -e '
import { createRequire } from "node:module";
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
const req = createRequire(import.meta.url);
const pkgPath = dirname(req.resolve("@re-cinq/eslint-plugin-re-lint/package.json"));
console.log("pkgPath:", pkgPath);
for (const f of ["rules/test-imports-its-subject.js", "rules/require-spec-link.js"]) {
  try {
    console.log("===" , f, "===");
    console.log(readFileSync(join(pkgPath, "dist", f), "utf8"));
  } catch (e) {
    console.log(e.message);
  }
}
'

node -e '
import { readFileSync, readdirSync } from "node:fs";
const base = "node_modules/@re-cinq/eslint-plugin-re-lint";
console.log(readdirSync(base + "/dist/rules"));
console.log("=== require-spec-link.js ===");
console.log(readFileSync(base + "/dist/rules/require-spec-link.js", "utf8"));
console.log("=== require-status-matches-coverage.js ===");
console.log(readFileSync(base + "/dist/rules/require-status-matches-coverage.js", "utf8"));
'

node -e '
import { readFileSync } from "node:fs";
const base = "node_modules/@re-cinq/eslint-plugin-re-lint/dist/rules";
console.log("=== require-spec-link.mjs ===");
